CREATE OR REPLACE FUNCTION public.admin_pipeline_page(_search text DEFAULT '',_stage text DEFAULT '',_source text DEFAULT '',_owner text DEFAULT '',_limit integer DEFAULT 25,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ WITH filtered AS (SELECT o.id,o.stage,to_jsonb(o)||jsonb_build_object('parties',jsonb_build_object('name_ar',p.name_ar,'tenant_code',p.tenant_code)) AS r,o.created_at FROM public.opportunities o LEFT JOIN public.parties_crm p ON p.id=o.party_id WHERE o.outcome IS NULL AND (_stage='' OR o.stage::text=_stage) AND (_source='' OR o.source::text=_source) AND (_owner='' OR (_owner='none' AND o.owner_user_id IS NULL) OR o.owner_user_id::text=_owner) AND (_search='' OR concat_ws(' ',p.name_ar,p.tenant_code) ILIKE '%'||_search||'%')), paged AS(SELECT r FROM filtered ORDER BY created_at DESC,id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(r) FROM paged),'[]'::jsonb),'count',(SELECT count(*) FROM filtered)); $$;
REVOKE ALL ON FUNCTION public.admin_pipeline_page(text,text,text,text,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_pipeline_page(text,text,text,text,integer,integer) TO authenticated;
SELECT to_regprocedure('public.admin_pipeline_page(text,text,text,text,integer,integer)') IS NOT NULL AS pipeline_page_ready;